#include "DeviceIdentityAttestation.h"
namespace dnxr { DeviceAttestationDecision DeviceIdentityAttestation::verify(const DeviceIdentityEvidence& e) const { DeviceAttestationDecision d; if(e.deviceId.empty()) d.blockers.push_back("device_id_missing"); if(e.certificate.size()<16U) d.blockers.push_back("device_certificate_invalid"); if(e.firmwareVersion.empty()) d.blockers.push_back("firmware_version_missing"); if(e.firmwareSignature.size()<16U) d.blockers.push_back("firmware_signature_invalid"); if(e.calibrationId.empty()) d.blockers.push_back("calibration_missing"); if(e.revoked) d.blockers.push_back("device_revoked"); d.trusted=d.blockers.empty(); return d; } }
